class TtlLru {
  constructor(maxEntries) { this.max = maxEntries; this.map = new Map(); }

  get(key) {
    const e = this.map.get(key);
    if (!e) return undefined;
    if (e.expires < Date.now()) { this.map.delete(key); return undefined; }
    return e.value;                       // read hit
  }

  set(key, value, ttlMs) {
    this.map.set(key, { value, expires: Date.now() + ttlMs });
    if (this.map.size > this.max) {
      const oldest = this.map.keys().next().value;  // first inserted
      this.map.delete(oldest);                       // evict it
    }
  }
}
